include <robotics.scad>
// RH56DFX wrist mounting flange. Origin: centre of the bottom mounting face.
OD = 52.0;      // official
PCD = 38.0;     // official circle (Fig.1 bottom view)
H = 8.5;        // measured from drawing
hole_d = 3.2;   // placeholder - not dimensioned
hole_depth = 6; // placeholder
diff() cyl(d = OD, h = H, chamfer = 0.5, anchor = BOT, $fn = 96) {
  tag("remove") position(BOT) down(0.01)
    for (a = [0, 90, 180, 270]) zrot(a) right(PCD/2) cyl(d = hole_d, h = hole_depth, anchor = BOT, $fn = 24);
}

include <robotics.scad>
// Wrist neck + palm housing envelope. Origin on the wrist axis at the floor (z=0).
W = 80.7;  T = 31.2;     // official palm width / thickness
z_fl = 8.5;              // flange top (measured)
z_neck = 34;             // neck waist (measured)
z_palm = 52;             // palm bottom (measured)
z_top = 133;             // knuckle line (measured)
r_v = 6;                 // vertical edge rounding (not dimensioned)
union() {
  // Neck: Ø52 round -> 48.5 x 44 oval -> palm rounded rectangle
  skin([circle(d = 52, $fn = 96),
        ellipse(d = [50.5, 49], $fn = 96),
        ellipse(d = [48.5, 44], $fn = 96),
        rect([W, T], rounding = r_v, $fn = 96)],
       z = [z_fl - 0.01, 20, z_neck, z_palm + 0.01], slices = 6, sampling = "segment");
  // Palm block
  up(z_palm) cuboid([W, T, z_top - z_palm], rounding = r_v, edges = [TOP, "Z"], anchor = BOT, $fn = 48);
}

include <robotics.scad>
// Finger proximal segment, origin at base centre on the palm top; ends at the PIP joint plane.
L = 35.5; w1 = 13; t1 = 16; w2 = 12.5; t2 = 15;
hull() {
  cuboid([w1, t1, 0.5], rounding = 4, edges = "Z", anchor = BOT, $fn = 32);
  up(L) cuboid([w2, t2, 0.5], rounding = 4, edges = "Z", anchor = TOP, $fn = 32);
}

include <robotics.scad>
// Finger distal segment, origin at the joint end. Tip pole vertex lands exactly at z = L.
L = 49.3; w1 = 12.5; t1 = 15; w2 = 11; t2 = 12;
hull() {
  cuboid([w1, t1, 0.5], rounding = 4, edges = "Z", anchor = BOT, $fn = 32);
  up(L - w2/2) scale([1, t2/w2, 1]) spheroid(d = w2, style = "aligned", $fn = 40);
}

