include <robotics.scad>
// World-frame thumb (right hand, thumb at +X opening toward the palm side -Y).
R  = [34, -12, 60];   // root inside palm (measured)
J  = [65, -45, 95];   // thumb joint (measured)
T  = [100, -74, 123]; // tip extreme (measured)
u  = unit(T - J);
half_of(-u, cp = J - 0.15*u)
  hull() {
    translate(R) sphere(r = 9, $fn = 40);
    translate(J) sphere(r = 8.5, $fn = 40);
  }

include <robotics.scad>
J  = [65, -45, 95];
T  = [100, -74, 123];
u  = unit(T - J);
rt = 6.5;
half_of(u, cp = J + 0.15*u)
  hull() {
    translate(J) sphere(r = 8.5, $fn = 40);
    translate(T - rt*u) sphere(r = rt, $fn = 40);
  }

